import { logForDebugging } from '../utils/debug.js'
import { shellQuote } from '../utils/shellArgument.js'

/** Only paths generated by this connection are eligible; never scan /tmp. */
export function remoteSocketCleanupCommand(socket: string): string {
  if (!/^\/tmp\/bgs-ssh-auth-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.sock$/.test(socket)) {
    throw new Error('Refusing to clean an unowned SSH socket path')
  }
  const path = shellQuote(socket)
  return `if [ -S ${path} ] && [ ! -L ${path} ]; then rm -f -- ${path}; fi`
}

/** Best effort after the owning SSH process exits, without blocking reconnect. */
export async function cleanupRemoteSocket(host: string, socket: string): Promise<void> {
  const command = remoteSocketCleanupCommand(socket)
  let proc: ReturnType<typeof Bun.spawn> | undefined
  let timer: ReturnType<typeof setTimeout> | undefined
  try {
    proc = Bun.spawn([
      'ssh', '-T', '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=3',
      '-o', 'ClearAllForwardings=yes', '-o', 'ControlPath=none',
      '-o', 'ControlMaster=no', '-o', 'ControlPersist=no',
      '--', host, command,
    ], { stdin: 'ignore', stdout: 'ignore', stderr: 'ignore' })
    // Cleanup must not keep the UI alive after the user exits.
    proc.unref()
    timer = setTimeout(() => {
      try { proc?.kill('SIGKILL') } catch { /* Process may already have exited. */ }
    }, 5_000)
    timer.unref()
    const code = await proc.exited
    if (code !== 0) logForDebugging(`[SSH] remote socket cleanup failed (exit ${code}); socket may remain`)
  } catch {
    logForDebugging('[SSH] remote socket cleanup failed; socket may remain')
  } finally {
    clearTimeout(timer)
  }
}
